export default {async fetch(req,env){try{const url=new URL(req.url);if(url.pathname.startsWith('/api/'))return await api(req,env);if(url.pathname==='/health')return json({ok:true,mode:env.COMMERCE_MODE||'disabled'});if(url.pathname==='/admin/'&&!admin(req,env))return Response.redirect(url.origin+'/signin-with-chatgpt?return_to=%2Fadmin%2F',302);return await env.ASSETS.fetch(req);}catch(e){if(!e.status)console.error('Store request failed',e.message);return json({error:e.status?e.message:'Store temporarily unavailable. Please try again.'},e.status||503);}}};
